from Registry import Registry

def check_region_info(system_reg, software_reg):
    # Check SYSTEM hive first
    current = system_reg.open("Select").value("Current").value()
    current_control_set = f"ControlSet00{current}"

    locations_system = [
        f"{current_control_set}\\Control\\Nls\\Language",
        f"{current_control_set}\\Control\\TimeZoneInformation"
    ]

    print("Checking SYSTEM hive:")
    for location in locations_system:
        try:
            key = system_reg.open(location)
            print(f"\nLocation: {location}")
            for value in key.values():
                print(f"{value.name()}: {value.value()}")
        except Exception as e:
            print(f"Error checking {location}: {e}")

    # Check SOFTWARE hive
    locations_software = [
        "Microsoft\\Windows NT\\CurrentVersion",
        "Microsoft\\Windows\\CurrentVersion\\WindowsUpdate"
    ]

    print("\nChecking SOFTWARE hive:")
    for location in locations_software:
        try:
            key = software_reg.open(location)
            print(f"\nLocation: {location}")
            for value in key.values():
                if any(x in value.name().lower() for x in ['location', 'region', 'country', 'territory']):
                    print(f"{value.name()}: {value.value()}")
        except Exception as e:
            print(f"Error checking {location}: {e}")

# Open registry hives
system_reg = Registry.Registry("ctf_files/SYSTEM")
software_reg = Registry.Registry("ctf_files/SOFTWARE")
check_region_info(system_reg, software_reg)
