from Registry import Registry
import binascii

def check_org_info(software_reg, sam_reg):
    print("Checking Organization and User Information:")

    # Check Windows registration info
    try:
        key = software_reg.open("Microsoft\\Windows NT\\CurrentVersion")
        print("\nWindows Registration Info:")
        for value in key.values():
            if any(x in value.name().lower() for x in ['owner', 'organization', 'registered']):
                print(f"{value.name()}: {value.value()}")
    except Exception as e:
        print(f"Error checking Windows registration: {e}")

    # Check installed products
    try:
        key = software_reg.open("Microsoft\\Windows\\CurrentVersion\\Installer\\UserData")
        print("\nInstalled Products:")
        for subkey in key.subkeys():
            try:
                for product in subkey.subkeys():
                    if product.name() == "Products":
                        for prod in product.subkeys():
                            try:
                                inst_key = prod.subkey("InstallProperties")
                                print(f"\nProduct:")
                                for value in inst_key.values():
                                    if any(x in value.name().lower() for x in ['owner', 'organization', 'location']):
                                        print(f"{value.name()}: {value.value()}")
                            except:
                                pass
            except:
                pass
    except Exception as e:
        print(f"Error checking installed products: {e}")

# Open registry hives
software_reg = Registry.Registry("ctf_files/SOFTWARE")
sam_reg = Registry.Registry("ctf_files/SAM")
check_org_info(software_reg, sam_reg)
